import{_ as a,o as t,c as p,a3 as l}from"./chunks/framework.d6OaePA7.js";const h=JSON.parse('{"title":"0917 小红书推广总结","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://scattter.github.io/pages/explore/share/0917-%E5%B0%8F%E7%BA%A2%E4%B9%A6%E6%8E%A8%E5%B9%BF%E6%80%BB%E7%BB%93.html"}]]},"headers":[],"relativePath":"pages/explore/share/0917-小红书推广总结.md","filePath":"pages/explore/share/0917-小红书推广总结.md","lastUpdated":1789698543000}'),r={name:"pages/explore/share/0917-小红书推广总结.md"};function i(s,e,o,_,c,n){return t(),p("div",null,[...e[0]||(e[0]=[l('<h1 id="_0917-小红书推广总结" tabindex="-1">0917 小红书推广总结 <a class="header-anchor" href="#_0917-小红书推广总结" aria-label="Permalink to &quot;0917 小红书推广总结&quot;">​</a></h1><p>自从 7 月份开始小程序开发, 中间经历过改名称, 改排版, 加宣传平台, 已经过去两个月了, 但是流量一直不好, 微信平台上看有 62 个用户, 拉了数据库后发现才有 54 个用户. 之前也一直在小红书上看到其他独立开发者的宣传贴, 有提到投流, 所以昨天晚上开始了第一次投流.</p><p>先说结果, 我投的是阅读量, 平台预期能给我增加 200 ~ 500 个阅读, 结果最后只有 170 个左右, 没有达标还给我退钱了... 这让我有点哭笑不得, 还真的把钱退给我了...</p><p>小红书投流有好几种目的, 比如增加上面说的阅读量, 还有曝光, 点赞, 关注, 主页访问等, 人群也能选择性别, 年龄阶段, 地区, 还能根据内容标签和消费标签筛选人群, 具体如下</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/cb87702b599814d026e0a232368cb9a9.jpg" alt=""></p><p>然后完整数据为</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/7419c29a8009beb6968a346f58a5ab5c.jpg" alt=""></p><p>昨天晚上 18:46 开始推广, 可以看到数据有点差, 推广地区比较分散, 这个影响不大; 年龄阶段主要集中在 23-30 中间, 这个阶段的女性大部分已经毕业以及开始和社会有自己的接触了, 一些人情往来/婚嫁是肯定会有的, 年龄也没啥问题, 也属于我产品的意向人群; 最后就是这个观众兴趣分布, 我选择了婚嫁, 而且这些帖子本身也是偏向于婚嫁, 但是没有给我推, 所以需要看看能不能联系客服咨询下.</p><p>除了上面这些我自己也想会不会是下面这些问题</p><ol><li><p>平台不适合</p><p>但是想想别人的能推广出去, 同质化的产品那么多都能推出去, 那就不是平台的问题</p></li><li><p>内容不行, 不够吸引用户</p><p>这个有可能, 现在的帖子相比于最开始的大字报好了很多, 但是依然是静态的, 没有动态图, 而且首页做的信息密度好像比较高? 一眼看上去会有点累, 吸引不了用户.</p></li><li><p>没有痛点, 产品没有解决问题, 或者说这是一个伪问题</p><p>这个有可能是最大的问题, 我简单看了微信官方的一些回流数据, 以及后台数据库的数据, 回流都比较差, 都是用了一次, 记录一些东西, 然后后面就没有再登录过了. 我还没有问过真实的用户, 计划后续问一下.</p></li></ol><p>最后总结一下, 两个 action:</p><ol><li>问下小红书投流选了婚嫁的 tag, 但是为什么没有推送到?</li><li>做下简单的用户访谈 <ol><li>了解下新用户对小程序, 首页的第一印象</li><li>了解下是不是没有解决问题, 伪需求</li></ol></li></ol>',12)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
